using Licitaciones.Application.TiposCambio;
namespace Licitaciones.Api.Endpoints.TiposCambio;
public sealed record TipoCambioRequest(decimal CrcPorUsd, bool Activo);
public static class TipoCambioEndpoints { public static IEndpointRouteBuilder MapTiposCambio(this IEndpointRouteBuilder a) { var g = a.MapGroup("/api/v1/tipos-cambio"); g.MapPost("", async (TipoCambioRequest r, TipoCambioService s, CancellationToken c) => Results.Created("", await s.CrearAsync(r.CrcPorUsd, r.Activo, c))); g.MapGet("", async (TipoCambioService s, CancellationToken c) => Results.Ok(await s.ListarAsync(c))); g.MapGet("/activo", async (TipoCambioService s, CancellationToken c) => Results.Ok(await s.ActivoAsync(c))); g.MapGet("/{id:guid}", async (Guid id, TipoCambioService s, CancellationToken c) => Results.Ok(await s.ObtenerAsync(id, c))); g.MapPut("/{id:guid}", async (Guid id, TipoCambioRequest r, TipoCambioService s, CancellationToken c) => { await s.EditarAsync(id, r.CrcPorUsd, r.Activo, c); return Results.NoContent(); }); g.MapDelete("/{id:guid}", async (Guid id, TipoCambioService s, CancellationToken c) => { await s.EliminarAsync(id, c); return Results.NoContent(); }); g.MapGet("/convertir/{crc:decimal}", async (decimal crc, TipoCambioService s, CancellationToken c) => Results.Ok(new { montoCrc = crc, montoUsd = await s.ConvertirCrcAUsdAsync(crc, c) })); return a; } }
